def checksum_md5(filename):
    md5 = hashlib.md5()
    with open(filename,'r') as f: 
        read = f.read()       
        md5.update(read.encode())
    return str(md5.hexdigest())


def byte_to_str(b):
    s = bytes.decode(b)
    return s

def sortid(elem):
    return elem["id"]

def calculate_md5(str):
    md5_hash = hashlib.md5()
    
    md5_hash.update(str.encode())

    return md5_hash.hexdigest()

